const first = $input.first();
const body = first ? first.json : null;
const cap = Number($("Config").first().json.maxSampleChars) || 2000;
if (!body || body.error || !body.data || !body.data.resultData) {
  const why = body && body.error ? (body.error.message || "API error") : "execution returned no runData";
  return [{ json: { recorder_blind: true, reason: why, tools: [], agents: [], evidence_truncated: false, nodes_seen: 0 } }];
}
const runData = body.data.resultData.runData || {};
const wfNodes = body.workflowData && Array.isArray(body.workflowData.nodes) ? body.workflowData.nodes : [];
const typeByName = {};
for (const n of wfNodes) { typeByName[n.name] = n.type || ""; }
function isTool(t) { return typeof t === "string" && t.toLowerCase().indexOf("tool") !== -1; }
function isAgent(t) { return typeof t === "string" && t.toLowerCase().indexOf("agent") !== -1; }
function pickOutput(r) {
  if (!r || !r.data) return [];
  if (Array.isArray(r.data.ai_tool) && Array.isArray(r.data.ai_tool[0])) return r.data.ai_tool[0];
  if (Array.isArray(r.data.main) && Array.isArray(r.data.main[0])) return r.data.main[0];
  return [];
}
function pickInput(r) {
  if (!r || !r.inputOverride) return {};
  if (Array.isArray(r.inputOverride.ai_tool) && Array.isArray(r.inputOverride.ai_tool[0])) return r.inputOverride.ai_tool[0];
  return r.inputOverride;
}
const tools = [];
const agents = [];
let truncated = false;
for (const name of Object.keys(runData)) {
  const t = typeByName[name] || "";
  const runs = Array.isArray(runData[name]) ? runData[name] : [];
  for (let i = 0; i < runs.length; i++) {
    const r = runs[i] || {};
    const outArr = pickOutput(r);
    let payloadError = false;
    let errText = "";
    for (const o of outArr) {
      if (o && o.json && o.json.error !== undefined && o.json.error !== null) {
        payloadError = true;
        if (!errText) errText = typeof o.json.error === "string" ? o.json.error : JSON.stringify(o.json.error);
      }
    }
    let outFull = "";
    try { outFull = JSON.stringify(outArr); } catch (e) { outFull = ""; }
    if (outFull.length > cap) truncated = true;
    let inFull = "";
    try { inFull = JSON.stringify(pickInput(r)); } catch (e) { inFull = ""; }
    if (inFull.length > cap) truncated = true;
    const nodeFailed = r.executionStatus === "error";
    const entry = { name: name, node_type: t, run: i, ok: !nodeFailed && !payloadError, node_failed: nodeFailed, payload_error: payloadError, error_text: String(errText).slice(0, 300), status: r.executionStatus || "unknown", ms: Number(r.executionTime) || 0, started_at: r.startTime || null, input_sample: inFull.slice(0, cap), output_sample: outFull.slice(0, cap) };
    if (isTool(t)) { tools.push(entry); } else if (isAgent(t)) { agents.push(entry); }
  }
}
return [{ json: { recorder_blind: false, reason: "", tools: tools, agents: agents, evidence_truncated: truncated, nodes_seen: Object.keys(runData).length } }];

const e = $input.first().json;
const cfg = $("Config").first().json;
const findings = [];
if (e.recorder_blind) {
  findings.push({ type: "RECORDER_BLIND", severity: "CRITICAL", detail: "could not read the execution record: " + e.reason + ". No claim was checked this run, so nothing here should be read as a clean bill of health." });
  return [{ json: { findings: findings, ledger: [], claims: [], evidence_complete: false, redactions: 0, tools_called: 0, tools_ok: 0, tools_failed: 0, answer_present: false } }];
}
const RED = [
  { re: new RegExp("sk-[A-Za-z0-9]{12,}", "g"), tag: "api_key" },
  { re: new RegExp("(bearer\\s+)[A-Za-z0-9._-]{12,}", "gi"), tag: "bearer_token" },
  { re: new RegExp("(password|passwd|secret|token|api[_-]?key)\\W{1,4}([A-Za-z0-9._-]{8,})", "gi"), tag: "secret_field" },
  { re: new RegExp("[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}", "g"), tag: "email" },
  { re: new RegExp("\\b[A-Fa-f0-9]{32,}\\b", "g"), tag: "long_hex_token" }
];
let redactions = 0;
const redactedTags = {};
function redact(s) {
  let out = String(s || "");
  for (const r of RED) {
    out = out.replace(r.re, function () { redactions++; redactedTags[r.tag] = true; return "[REDACTED:" + r.tag + "]"; });
  }
  return out;
}
const ledger = [];
for (const t of e.tools) {
  ledger.push({ tool: t.name, node_type: t.node_type, run: t.run, ok: t.ok, node_failed: t.node_failed, payload_error: t.payload_error, error_text: redact(t.error_text), status: t.status, ms: t.ms, input: redact(t.input_sample), output: redact(t.output_sample) });
}
let answer = "";
for (const a of e.agents) { answer += " " + redact(a.output_sample); }
const lower = answer.toLowerCase();
const SIDE_EFFECT = ["sent", "emailed", "created", "updated", "deleted", "posted", "booked", "cancelled", "refunded", "scheduled", "saved", "published", "uploaded", "notified", "charged"];
const READ_ONLY = ["searched", "looked up", "checked", "fetched", "retrieved", "queried"];
const claims = [];
for (const v of SIDE_EFFECT) { if (lower.indexOf(v) !== -1) { claims.push({ verb: v, kind: "side_effect" }); } }
for (const v of READ_ONLY) { if (lower.indexOf(v) !== -1) { claims.push({ verb: v, kind: "read" }); } }
const seen = {};
const uniqueClaims = [];
for (const c of claims) { if (!seen[c.verb]) { seen[c.verb] = true; uniqueClaims.push(c); } }
const okCalls = ledger.filter(function (l) { return l.ok; });
const failedCalls = ledger.filter(function (l) { return !l.ok; });
const hasAnswer = answer.trim().length > 0;
const sideEffectClaims = uniqueClaims.filter(function (c) { return c.kind === "side_effect"; });
if (!hasAnswer) {
  findings.push({ type: "NO_AGENT_OUTPUT", severity: "HIGH", detail: "no agent answer was found in this execution, so no claim could be compared against the tool ledger. Point the recorder at an execution that contains an AI Agent node." });
} else if (sideEffectClaims.length > 0 && okCalls.length === 0) {
  const verbs = sideEffectClaims.map(function (c) { return c.verb; }).join(", ");
  findings.push({ type: "FABRICATED_ACTION", severity: "CRITICAL", detail: "the agent described doing something with real-world effect (" + verbs + ") but the execution record contains no successful tool call at all. Either the action never happened, or it happened somewhere this recorder cannot see." });
}
if (failedCalls.length > 0 && hasAnswer) {
  const admits = lower.indexOf("fail") !== -1 || lower.indexOf("error") !== -1 || lower.indexOf("could not") !== -1 || lower.indexOf("couldn") !== -1 || lower.indexOf("unable") !== -1 || lower.indexOf("problem") !== -1 || lower.indexOf("no orders") !== -1 || lower.indexOf("not find") !== -1 || lower.indexOf("no results") !== -1;
  if (!admits) {
    const parts = [];
    for (const l of failedCalls) { parts.push(l.tool + (l.payload_error ? " returned \"" + l.error_text + "\"" : " failed at node level")); }
    findings.push({ type: "SILENT_RECOVERY", severity: "HIGH", detail: "a tool did not succeed (" + parts.join("; ") + ") but the agent answer never mentions any failure or missing data. The agent wrote around a broken step, which reads to the user exactly like success." });
  }
}
const byToolInput = {};
for (const l of ledger) { const k = l.tool + "|" + l.input; byToolInput[k] = (byToolInput[k] || 0) + 1; }
for (const k of Object.keys(byToolInput)) {
  if (byToolInput[k] > 1) {
    const toolName = k.split("|")[0];
    findings.push({ type: "DUPLICATE_SIDE_EFFECT", severity: "CRITICAL", detail: "tool \"" + toolName + "\" ran " + byToolInput[k] + " times with identical input. If that tool is not idempotent the action happened more than once - the classic retry-after-timeout double send." });
  }
}
const byTool = {};
for (const l of ledger) { byTool[l.tool] = (byTool[l.tool] || 0) + 1; }
const stormLimit = Number(cfg.retryStormThreshold) || 3;
for (const k of Object.keys(byTool)) {
  if (byTool[k] > stormLimit) {
    findings.push({ type: "RETRY_STORM", severity: "HIGH", detail: "tool \"" + k + "\" was called " + byTool[k] + " times in one run, over the threshold of " + stormLimit + ". An agent that is handed an error and told to cope will often just try again forever." });
  }
}
if (redactions > 0) {
  findings.push({ type: "SECRET_IN_EVIDENCE", severity: "CRITICAL", detail: redactions + " secret-shaped value(s) (" + Object.keys(redactedTags).join(", ") + ") appeared in tool inputs or outputs and were masked before this record was stored. The values are out of the record, but they were in the agent context, so treat them as exposed and rotate." });
}
const INJ = ["ignore previous", "ignore all previous", "disregard the above", "system:", "you are now", "new instructions"];
for (const l of ledger) {
  const lo = String(l.output || "").toLowerCase();
  for (const p of INJ) {
    if (lo.indexOf(p) !== -1) {
      findings.push({ type: "INJECTION_ECHO", severity: "HIGH", detail: "the output of tool \"" + l.tool + "\" contains instruction-shaped text (\"" + p + "\"). Tool output is untrusted input. Once tool output is stored in memory it gets replayed into every later run." });
      break;
    }
  }
}
if (e.evidence_truncated) {
  findings.push({ type: "EVIDENCE_TRUNCATED", severity: "HIGH", detail: "at least one tool input or output was larger than the sample cap and was stored only in part. Any verdict below rests on an incomplete record and is provisional." });
}
return [{ json: { findings: findings, ledger: ledger, claims: uniqueClaims, evidence_complete: !e.evidence_truncated, redactions: redactions, tools_called: ledger.length, tools_ok: okCalls.length, tools_failed: failedCalls.length, answer_present: hasAnswer } }];

const r = $input.first().json;
const cfg = $("Config").first().json;
const nowIso = new Date().toISOString();
const findings = Array.isArray(r.findings) ? r.findings : [];
let critical = 0;
let high = 0;
for (const f of findings) { if (f.severity === "CRITICAL") critical++; if (f.severity === "HIGH") high++; }
const blind = findings.some(function (f) { return f.type === "RECORDER_BLIND"; });
let verdict = "CLEAN";
if (critical > 0) { verdict = "BREACH"; } else if (high > 0) { verdict = "SUSPECT"; }
if ((blind || r.evidence_complete === false) && verdict === "CLEAN") { verdict = "UNVERIFIED"; }
const canonical = JSON.stringify({ ledger: r.ledger || [], claims: r.claims || [], findings: findings });
let h1 = 2166136261;
let h2 = 5381;
for (let i = 0; i < canonical.length; i++) {
  const c = canonical.charCodeAt(i);
  h1 = (h1 ^ c) >>> 0;
  h1 = (h1 + ((h1 << 1) + (h1 << 4) + (h1 << 7) + (h1 << 8) + (h1 << 24))) >>> 0;
  h2 = (((h2 << 5) + h2) + c) >>> 0;
}
const fingerprint = ("00000000" + h1.toString(16)).slice(-8) + ("00000000" + h2.toString(16)).slice(-8);
const coverage = blind ? "no record - nothing was checked" : (r.evidence_complete === false ? "partial record - verdict is provisional" : "full record for " + (r.tools_called || 0) + " tool call(s)");
const lines = [];
for (const f of findings) { lines.push("- [" + f.severity + "] " + f.type + ": " + f.detail); }
const alertText = "Agent Flight Recorder: " + verdict + "\nExecution: " + cfg.execution_id + "\nCoverage: " + coverage + "\nFingerprint: " + fingerprint + "\n\n" + (lines.length ? lines.join("\n") : "No findings.");
return [{ json: {
  pack_key: "PACK:" + String(cfg.execution_id) + ":" + fingerprint,
  execution_id: String(cfg.execution_id),
  workflow_id: "",
  verdict: verdict,
  fingerprint: fingerprint,
  tools_called: Number(r.tools_called) || 0,
  claims_made: Array.isArray(r.claims) ? r.claims.length : 0,
  claims_unsupported: findings.filter(function (f) { return f.type === "FABRICATED_ACTION"; }).length,
  coverage: coverage,
  findings: JSON.stringify(findings),
  recorded_at: nowIso,
  alert_text: alertText,
  critical_count: critical,
  high_count: high
} }];

